insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"articles_a_an_homework_q01_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an_homework.yaml","source_metadata":{}},{"key":"articles_a_an_homework_q01_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"articles_a_an_homework_q01_finish","locale":"he","line_order":0,"content":"כל הקשרים ברשת חזקים. מלכת הים תהיה גאה בכם.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: המילה שבאה מיד אחרי a או an מחליטה. אם היא מתחילה ב־a, e, i, o, u, אומרים an.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_homework_q01_finish","locale":"he","line_order":2,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב. הרשת החדשה מחזיקה חזק, ומחר מלכת הים מגיעה לבדוק אותה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_homework_q01_start","locale":"he","line_order":1,"content":"היום אין כלל חדש. אני רק רוצה לראות שאתם זוכרים לבד מתי a ומתי an.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_homework_q01_start","locale":"he","line_order":2,"content":"כל תשובה נכונה היא עוד קשר חזק ברשת. התיבה ליד המים מחכה לכם.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
